<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";function countRows($conn,$sql){$r=$conn->query($sql)->fetch_row();return (int)$r[0];}$students=countRows($conn,"SELECT COUNT(*) FROM users WHERE role='student'");$clubs=countRows($conn,'SELECT COUNT(*) FROM clubs');$events=countRows($conn,'SELECT COUNT(*) FROM events');$regs=countRows($conn,'SELECT COUNT(*) FROM event_registrations');$popularClubs=$conn->query("SELECT c.club_name,COUNT(cm.member_id) total FROM clubs c LEFT JOIN club_members cm ON cm.club_id=c.club_id GROUP BY c.club_id ORDER BY total DESC LIMIT 5");$popularEvents=$conn->query("SELECT e.event_name,COUNT(r.registration_id) total FROM events e LEFT JOIN event_registrations r ON r.event_id=e.event_id GROUP BY e.event_id ORDER BY total DESC LIMIT 5");?>
<!doctype html><html><head><title>Analytics</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Admin Analytics</div><div class="nav-links"><a href="dashboard.php">Dashboard</a><a href="reports.php">Reports</a><a href="../logout.php">Logout</a></div></nav><div class="container"><h1>Participation Analytics</h1><div class="grid"><div class="stat"><div class="muted">Students</div><h2><?=$students?></h2></div><div class="stat"><div class="muted">Clubs</div><h2><?=$clubs?></h2></div><div class="stat"><div class="muted">Events</div><h2><?=$events?></h2></div><div class="stat"><div class="muted">Registrations</div><h2><?=$regs?></h2></div></div><h2>Popular Clubs</h2><?php while($r=$popularClubs->fetch_assoc()):?><div class="card"><b><?=htmlspecialchars($r['club_name'])?></b> <span class="muted">- <?=$r['total']?> members</span></div><br><?php endwhile;?><h2>Popular Events</h2><?php while($r=$popularEvents->fetch_assoc()):?><div class="card"><b><?=htmlspecialchars($r['event_name'])?></b> <span class="muted">- <?=$r['total']?> registrations</span></div><br><?php endwhile;?></div></body></html>
